/* Contenido profundo de es_p2 (borrador para revisión del equipo curricular; ver "verify" por unidad). */
window.EL_DEEP = window.EL_DEEP || {};
Object.assign(window.EL_DEEP, {"p2:Oct": {"reading": ["Todas las personas vivimos en algún lugar. Puede ser un pueblo pequeño o una ciudad grande, pero siempre es un municipio. Un municipio es el territorio donde viven los vecinos y que gobierna un ayuntamiento. Antes de ser como hoy lo vemos, cada municipio tuvo un principio. Alguien llegó, construyó las primeras casas y se quedó a vivir. Para conocerla podemos preguntar a los abuelos, visitar el museo o leer los libros de la biblioteca.", "Muchos lugares nacieron junto a un río, en lo alto de una colina o cerca del mar. La gente elegía sitios donde hubiera agua, tierra buena para cultivar y protección frente a los peligros. Con el tiempo llegaban más familias y el lugar crecía. Se levantaban una plaza, una iglesia, un mercado y calles nuevas. Por eso, cuando paseas por tu ciudad, cada edificio antiguo te cuenta un trozo de esa historia.", "En casi todas las ciudades hay un personaje histórico que es recordado con cariño. Puede ser un santo, un maestro, un artista, un marinero o un gobernante justo. Su nombre aparece en una calle, en una plaza o en una estatua. Cuando lo estudiamos, aprendemos tres cosas: cómo se llamaba, en qué época vivió y por qué se hizo famoso. Recordar a estas personas es una forma de dar las gracias.", "El escudo municipal es el dibujo que representa a la ciudad. Aparece en el ayuntamiento, en los documentos oficiales y en las banderas. Cada dibujo del escudo tiene un significado. Un castillo recuerda que el lugar fue defendido. Un río o unas ondas hablan del agua. Un árbol, una torre o un animal pueden señalar una historia antigua o una riqueza propia del lugar.", "La Biblia nos da un consejo muy bonito sobre la ciudad. Dios dijo a su pueblo que buscara la paz de la ciudad donde vivía y que orara por ella. Los niños también podemos hacerlo. Cuidamos la calle sin tirar basura, saludamos a los vecinos y respetamos los jardines. Así damos las gracias a Dios por el lugar donde nos puso a vivir."], "glossary": [{"term": "Municipio", "def": "Territorio con sus habitantes, gobernado por un ayuntamiento; puede ser un pueblo o una ciudad."}, {"term": "Ayuntamiento", "def": "Edificio y grupo de personas que cuidan y organizan los servicios del municipio."}, {"term": "Fundación", "def": "Momento en que se crea un lugar o una institución y empieza su historia."}, {"term": "Personaje histórico", "def": "Persona del pasado que hizo algo importante y que se recuerda por ello."}, {"term": "Escudo", "def": "Dibujo con símbolos que representa a un municipio, una región o una familia."}, {"term": "Símbolo", "def": "Imagen o signo que representa una idea, como un castillo que recuerda la defensa de la ciudad."}], "practice": [{"q": "¿Por qué muchos pueblos y ciudades nacieron cerca de un río o del mar?", "feedback": "Las primeras familias necesitaban agua para beber, para regar los cultivos y para vivir. Un río o el mar también daba alimento, como los peces, y facilitaba el viaje y el comercio. Elegían además lugares fáciles de defender. Por eso muchos municipios nacieron en esos sitios. Todo esto nos recuerda que Dios provee lo que necesitamos."}, {"q": "Explica con tus palabras qué es un escudo municipal y para qué sirve.", "feedback": "Un escudo es un dibujo con símbolos que representa a una ciudad o a un pueblo. Sirve para que todos reconozcan al municipio en el ayuntamiento, en las banderas y en los papeles oficiales. Cada figura y cada color cuentan algo de su historia. Por eso conviene mirar el escudo con atención para entenderlo."}, {"q": "Jeremías 29:7 nos pide buscar la paz de la ciudad. Escribe dos acciones con las que tú puedes cuidar tu ciudad esta semana.", "feedback": "Hay muchas respuestas buenas, por ejemplo tirar la basura en la papelera, saludar a los vecinos o ayudar a cuidar una plaza. Lo importante es que sean acciones que tú puedas hacer de verdad. Buscar la paz de la ciudad significa tratar bien a los demás y cuidar lo que es de todos. También podemos orar por las personas que viven allí."}], "quiz": [{"q": "¿Qué es un municipio?", "opts": [{"t": "Solo una casa muy grande", "ok": false}, {"t": "Un territorio con sus habitantes, gobernado por un ayuntamiento", "ok": true}, {"t": "Un tipo de mapa", "ok": false}]}, {"q": "Según la lectura, ¿por qué elegían la gente ciertos lugares para fundar una ciudad?", "opts": [{"t": "Porque había agua, tierra buena y protección", "ok": true}, {"t": "Porque estaba cerca de una fábrica", "ok": false}, {"t": "Porque ya había muchos coches", "ok": false}]}, {"q": "¿Qué tres cosas aprendemos al estudiar a un personaje histórico?", "opts": [{"t": "Su color favorito, su comida y su mascota", "ok": false}, {"t": "Cuánto medía, cuánto pesaba y dónde dormía", "ok": false}, {"t": "Su nombre, su época y por qué es famoso", "ok": true}]}, {"q": "¿Qué puede significar un castillo en el escudo de una ciudad?", "opts": [{"t": "Que allí no hay agua", "ok": false}, {"t": "Que el lugar fue defendido en el pasado", "ok": true}, {"t": "Que todos los vecinos son reyes", "ok": false}]}, {"q": "¿Qué consejo da la Biblia sobre la ciudad donde vivimos?", "opts": [{"t": "Buscar su paz y orar por ella", "ok": true}, {"t": "Irse a otra ciudad", "ok": false}, {"t": "No hablar con los vecinos", "ok": false}]}], "verify": ["Jeremías 29:7: el texto bíblico se dirige al pueblo desterrado en Babilonia; confirmar la redacción exacta con la versión que use el centro.", "El origen y el escudo concretos dependen del municipio de cada familia; la lectura solo ofrece ejemplos generales."], "timeline": [{"when": "Paso 1", "what": "Alguien llega y construye las primeras casas."}, {"when": "Paso 2", "what": "Se elige un sitio con agua, tierra buena y protección."}, {"when": "Paso 3", "what": "Llegan más familias y el lugar crece."}, {"when": "Paso 4", "what": "Se levantan la plaza, la iglesia, el mercado y las calles."}, {"when": "Paso 5", "what": "Un personaje querido da nombre a calles y estatuas."}, {"when": "Paso 6", "what": "El escudo representa la historia de la ciudad."}], "scene": {"icons": ["🏘️", "🏛️", "📜"], "palette": "amber"}, "media": [{"title": "Escudo de Madrid", "what": "Ejemplo de escudo municipal con sus dibujos y su significado.", "find": "Escudo de Madrid Wikimedia Commons", "note": "Heráldica municipal; verificar licencia de la versión elegida."}, {"title": "Plaza Mayor de Salamanca", "what": "Muestra una plaza antigua con edificios que cuentan la historia de una ciudad.", "find": "Plaza Mayor de Salamanca Wikimedia Commons", "note": "Siglo XVIII; fotografía moderna, verificar licencia."}, {"title": "Ayuntamiento de Sevilla", "what": "Edificio donde trabaja el ayuntamiento que gobierna un municipio.", "find": "Ayuntamiento de Sevilla fachada Wikimedia Commons", "note": "Siglo XVI; fotografía moderna, verificar licencia."}]}, "p2:Nov": {"reading": ["España es un país muy grande y muy variado. Para conocerlo mejor, lo dividimos en partes. La parte más pequeña que ya conoces es el municipio. Varios municipios cercanos forman una provincia. Una provincia es como una familia de pueblos y ciudades que comparten un territorio y algunos servicios. Cada provincia tiene una capital, que es su ciudad principal.", "Varias provincias juntas forman una comunidad autónoma. En España hay diecisiete comunidades autónomas, y además dos ciudades autónomas, Ceuta y Melilla. Algunas comunidades tienen muchas provincias y otras solo una. Cada comunidad tiene su capital, su bandera, su escudo y, muchas veces, su himno. Estos símbolos ayudan a sus habitantes a sentirse parte de un mismo lugar. Cada comunidad tiene también su gobierno, que cuida de asuntos cercanos a la gente, como las escuelas o los hospitales.", "Un mapa es un dibujo del territorio visto desde arriba. En el mapa de tu comunidad puedes ver las provincias, separadas por líneas, y las capitales, marcadas con puntos. Para leerlo bien hay que mirar el título, los colores y la leyenda, que explica lo que significa cada signo. Colorear cada provincia de un color distinto ayuda a no confundirlas.", "Cuando miramos todas las comunidades de España, descubrimos que son muy distintas. Hay montañas, llanuras, playas e islas. Hay comidas, fiestas y paisajes diferentes. Incluso se hablan lenguas distintas. Esa variedad no divide a los españoles, sino que enriquece al país, igual que un jardín es más hermoso con flores de muchas clases.", "La Biblia dice que del Señor es la tierra y todo lo que hay en ella. Esto significa que cada valle, cada río y cada ciudad fue creado por Dios. Él nos ha dado un lugar donde vivir y quiere que lo cuidemos con respeto. Por eso, al aprender el nombre de nuestra provincia y de nuestra comunidad, también damos gracias al Creador."], "glossary": [{"term": "Provincia", "def": "Conjunto de municipios vecinos que forman una división del territorio, con una ciudad capital."}, {"term": "Comunidad autónoma", "def": "Región formada por una o varias provincias, con su propio gobierno, símbolos y capital."}, {"term": "Capital", "def": "Ciudad principal de una provincia, de una comunidad o de un país, donde está su gobierno."}, {"term": "Himno", "def": "Canción solemne que representa a un país, una región o un grupo de personas."}, {"term": "Mapa", "def": "Dibujo del territorio visto desde arriba, con signos y colores que explican lo que hay en él."}, {"term": "Leyenda", "def": "Parte del mapa que explica el significado de sus signos y colores."}], "practice": [{"q": "Explica con tus palabras la diferencia entre un municipio, una provincia y una comunidad autónoma.", "feedback": "El municipio es la parte más pequeña: un pueblo o una ciudad con su ayuntamiento. Varios municipios cercanos forman una provincia. Varias provincias, o a veces solo una, forman una comunidad autónoma. Es como las muñecas rusas, que van de lo pequeño a lo grande."}, {"q": "¿Para qué sirve la leyenda de un mapa? Da un ejemplo.", "feedback": "La leyenda explica qué significa cada color o cada signo del mapa. Por ejemplo, un punto negro puede señalar una capital y una línea gruesa puede separar dos provincias. Sin leyenda podríamos entender mal el mapa. Por eso siempre debemos mirarla antes de leer el dibujo."}, {"q": "¿Por qué la variedad de regiones de España es una riqueza y no un problema?", "feedback": "Cada región aporta paisajes, comidas, fiestas y costumbres propias, y así el país tiene mucho que ofrecer. Aprender de las demás regiones nos ayuda a valorar lo que tenemos en común y lo que nos distingue. Es como un jardín con flores de muchas clases. La Biblia nos enseña que toda la tierra es de Dios, y por eso podemos dar gracias por todos sus rincones."}], "quiz": [{"q": "¿Qué forman varios municipios cercanos?", "opts": [{"t": "Una provincia", "ok": true}, {"t": "Un escudo", "ok": false}, {"t": "Una leyenda", "ok": false}]}, {"q": "¿Qué es una comunidad autónoma?", "opts": [{"t": "Un tipo de himno", "ok": false}, {"t": "Una calle muy larga", "ok": false}, {"t": "Una región formada por una o varias provincias, con su propio gobierno", "ok": true}]}, {"q": "¿Para qué sirve la leyenda de un mapa?", "opts": [{"t": "Para contar un cuento", "ok": false}, {"t": "Para explicar lo que significan sus signos y colores", "ok": true}, {"t": "Para adornar el título", "ok": false}]}, {"q": "¿Qué dice la lectura sobre la variedad de las regiones?", "opts": [{"t": "Que causa muchos problemas", "ok": false}, {"t": "Que enriquece al país como un jardín con muchas flores", "ok": true}, {"t": "Que es mejor que todas sean iguales", "ok": false}]}, {"q": "¿Qué enseña el Salmo 24:1?", "opts": [{"t": "Que la tierra es de quien la compra", "ok": false}, {"t": "Que la tierra no importa", "ok": false}, {"t": "Que del Señor es la tierra y todo lo que hay en ella", "ok": true}]}], "verify": ["Número de comunidades autónomas (17) y ciudades autónomas (2): dato consolidado, confirmar.", "Algunas comunidades no tienen himno con letra; la actividad de aprender la letra depende de la comunidad de cada familia."], "timeline": [{"when": "Paso 1", "what": "El municipio es la parte más pequeña que conocemos."}, {"when": "Paso 2", "what": "Varios municipios cercanos forman una provincia."}, {"when": "Paso 3", "what": "Cada provincia tiene una capital, su ciudad principal."}, {"when": "Paso 4", "what": "Varias provincias forman una comunidad autónoma."}, {"when": "Paso 5", "what": "Cada comunidad tiene bandera, escudo y gobierno propio."}, {"when": "Paso 6", "what": "Leemos el mapa con título, colores y leyenda."}], "scene": {"icons": ["🗺️", "🧭", "🇪🇸"], "palette": "green"}, "media": [{"title": "Mapa político de España con comunidades autónomas", "what": "Muestra las comunidades y provincias separadas por líneas.", "find": "Mapa de las comunidades autónomas de España Wikimedia Commons", "note": "Mapa libre; verificar licencia de la versión elegida."}, {"title": "Bandera de España", "what": "Símbolo común a todos los españoles, junto a las banderas de cada comunidad.", "find": "Bandera de España Wikimedia Commons", "note": "Dominio público (diseño oficial)."}, {"title": "Mapa de las provincias de España", "what": "Permite colorear y distinguir cada provincia y su capital.", "find": "Mapa de provincias de España Wikimedia Commons", "note": "Verificar licencia."}]}, "p2:Dic": {"reading": ["La Navidad es una fiesta en la que recordamos el nacimiento de Jesús. En España se celebra en todas partes, pero cada región tiene sus propias costumbres. Esas costumbres se llaman tradiciones. Pasan de abuelos a padres y de padres a hijos, y por eso las queremos tanto.", "Todo comenzó en Belén. El Evangelio de Lucas cuenta que María y José viajaron a esa ciudad. Allí nació Jesús y fue colocado en un pesebre. Unos pastores que cuidaban sus ovejas recibieron la noticia por medio de un ángel. Ellos fueron a ver al niño y contaron a todos lo que habían visto. Más tarde, unos sabios de Oriente llegaron para adorarlo y le ofrecieron regalos. Este relato es la fuente de todas las tradiciones de Navidad.", "En muchos hogares de España se monta el belén o nacimiento. Son pequeñas figuras de María, José, el niño, los pastores y los animales. Cada región le da su toque especial, con paisajes y personajes de su tierra. También se cantan villancicos. Son canciones sencillas que cuentan el nacimiento de Jesús con alegría. Muchos de ellos se cantan desde hace siglos y los conocen niños de todo el país.", "Las comidas de Navidad cambian según el lugar. En unas regiones se toma marisco y en otras cordero, y en casi todas hay dulces como el turrón o los mantecados. Hay costumbres propias de algunas zonas, como el Tió de Cataluña, un tronco al que los niños cantan para recibir regalos, o el Olentzero del País Vasco, un carbonero que anuncia la Navidad. El día de Reyes, el seis de enero, es muy esperado en todo el país, porque recuerda la visita de los sabios de Oriente.", "Aunque las costumbres sean distintas, todas hablan de lo mismo: Dios se hizo niño por amor a nosotros. El ángel dijo a los pastores que había nacido el Salvador. Por eso la mejor manera de celebrar la Navidad es dar gracias y compartir con los demás."], "glossary": [{"term": "Tradición", "def": "Costumbre que se transmite de generación en generación dentro de una familia o un pueblo."}, {"term": "Belén", "def": "Ciudad donde nació Jesús; también se llama así a la representación con figuras de su nacimiento."}, {"term": "Villancico", "def": "Canción popular de Navidad que cuenta con alegría el nacimiento de Jesús."}, {"term": "Pesebre", "def": "Lugar donde come el ganado; allí fue colocado Jesús al nacer."}, {"term": "Salvador", "def": "Título de Jesús: el que viene a rescatarnos del pecado y a darnos vida."}, {"term": "Región", "def": "Parte de un país que se distingue por su territorio y sus costumbres."}], "practice": [{"q": "Cuenta con tus palabras cómo nació Jesús según el Evangelio de Lucas.", "feedback": "María y José viajaron a Belén. Allí nació Jesús y María lo acostó en un pesebre. Un ángel avisó a los pastores de que había nacido el Salvador, y ellos fueron a verlo. Después contaron a todos lo que habían visto. Este relato es el origen de la fiesta de la Navidad."}, {"q": "¿Qué es una tradición? Pon un ejemplo de tu familia o de tu región.", "feedback": "Una tradición es una costumbre que se repite cada año y que pasa de unos a otros. Por ejemplo, montar el belén, cantar villancicos o preparar un dulce especial. Lo importante es que tu ejemplo sea real y que lo expliques con claridad. Las tradiciones nos unen a la familia y nos recuerdan de dónde venimos."}, {"q": "¿Por qué, aunque las costumbres navideñas sean diferentes, todas las regiones celebran lo mismo?", "feedback": "Todas las regiones recuerdan el nacimiento de Jesús, que es la fuente de la fiesta. Cambian la comida, las canciones o los personajes, pero el motivo de la alegría es el mismo. El ángel anunció que había nacido el Salvador y esa noticia es para todos. Por eso, cada región celebra a su manera una misma buena noticia."}], "quiz": [{"q": "¿En qué ciudad nació Jesús según la lectura?", "opts": [{"t": "En Belén", "ok": true}, {"t": "En Madrid", "ok": false}, {"t": "En Roma", "ok": false}]}, {"q": "¿Quién avisó a los pastores del nacimiento de Jesús?", "opts": [{"t": "Un rey", "ok": false}, {"t": "Un ángel", "ok": true}, {"t": "Un vecino", "ok": false}]}, {"q": "¿Qué es un villancico?", "opts": [{"t": "Una comida típica", "ok": false}, {"t": "Un tipo de regalo", "ok": false}, {"t": "Una canción de Navidad que cuenta el nacimiento de Jesús", "ok": true}]}, {"q": "¿Qué recuerda el día de Reyes, el seis de enero?", "opts": [{"t": "La visita de los sabios de Oriente al niño Jesús", "ok": true}, {"t": "El comienzo del año escolar", "ok": false}, {"t": "La llegada del verano", "ok": false}]}, {"q": "¿Qué tienen en común todas las tradiciones navideñas?", "opts": [{"t": "Todas usan la misma comida", "ok": false}, {"t": "Todas hablan de que Dios se hizo niño por amor", "ok": true}, {"t": "Todas se celebran en verano", "ok": false}]}], "verify": ["Tió de Cataluña y Olentzero del País Vasco: confirmar la descripción de ambas costumbres.", "Lucas 2:11 y relato de los sabios de Oriente (Mateo 2): confirmar que la lectura distingue bien ambos Evangelios.", "La tradición concreta de cada comunidad autónoma depende de la familia; la lectura solo da ejemplos."], "timeline": [{"when": "Paso 1", "what": "María y José viajan a Belén."}, {"when": "Paso 2", "what": "Jesús nace y es colocado en un pesebre."}, {"when": "Paso 3", "what": "Un ángel anuncia la noticia a los pastores."}, {"when": "Paso 4", "what": "Los pastores visitan al niño y lo cuentan."}, {"when": "Paso 5", "what": "Unos sabios de Oriente llegan y le ofrecen regalos."}, {"when": "Paso 6", "what": "El seis de enero se celebra el día de Reyes."}], "scene": {"icons": ["⭐", "🐑", "🎄"], "palette": "violet"}, "media": [{"title": "La adoración de los pastores (Murillo)", "what": "Pintura que muestra a los pastores visitando al niño Jesús.", "find": "Murillo Adoración de los pastores Wikimedia Commons", "note": "Bartolomé Esteban Murillo, siglo XVII; dominio público."}, {"title": "La adoración de los Magos (Velázquez)", "what": "Pintura de los sabios de Oriente que ofrecen regalos a Jesús.", "find": "Velázquez Adoración de los Magos Museo del Prado Wikimedia Commons", "note": "Diego Velázquez, 1619; dominio público."}, {"title": "Belén o nacimiento tradicional", "what": "Fotografía de un belén con figuras de María, José, el niño y los pastores.", "find": "belén nacimiento navideño España Wikimedia Commons", "note": "Fotografía moderna; verificar licencia."}]}, "p2:Feb": {"reading": ["Escribir bien es como dibujar con palabras. Cuando escribimos, otra persona puede entender lo que pensamos sin que estemos a su lado. Por eso es importante escribir con claridad. Hoy vamos a aprender dos clases de textos: el texto descriptivo y el texto narrativo.", "El texto descriptivo dice cómo es algo. Puede describir una persona, un animal, una casa o un lugar. Para describir bien, observamos con atención y usamos los cinco sentidos. Podemos decir cómo se ve, cómo suena, cómo huele o cómo se siente. Por ejemplo: «Mi calle es estrecha y tiene muchas macetas con flores. Por la mañana huele a pan recién hecho». Los adjetivos, como estrecha, alegre o antigua, son palabras muy útiles para describir.", "El texto narrativo cuenta lo que sucede. Una narración tiene tres partes. En el inicio se presenta a los personajes y el lugar. En el nudo ocurre el problema o lo más importante. En el desenlace todo se resuelve. Por ejemplo: «Un sábado salí con mi familia al campo. De pronto se nos perdió el perro. Después de buscarlo un rato, lo encontramos dormido bajo un árbol». Para ordenar la historia usamos palabras como primero, luego, después y por último.", "Además de ordenar las ideas, debemos cuidar la ortografía. Estas son algunas reglas básicas. Las oraciones empiezan con letra mayúscula y terminan con punto. Los nombres propios, como España o Lucía, también llevan mayúscula. Se escribe «mb» y «mp» con m antes de b y de p, como en campo y también. Se escribe «ll» en palabras como lluvia y «y» en palabras como yo. Si dudamos, podemos mirar el diccionario.", "La Biblia nos aconseja hablar y escribir con cuidado, sin precipitarnos. Quien piensa antes de escribir ordena mejor sus ideas y respeta al lector. Por eso conviene releer, corregir y mejorar el texto. Escribir con claridad es una forma de servir a los demás."], "glossary": [{"term": "Texto descriptivo", "def": "Texto que explica cómo es una persona, un animal, un objeto o un lugar."}, {"term": "Texto narrativo", "def": "Texto que cuenta una historia con personajes y hechos ordenados en el tiempo."}, {"term": "Adjetivo", "def": "Palabra que dice cómo es un nombre, como alegre, antigua o estrecha."}, {"term": "Nudo", "def": "Parte de la narración en la que ocurre el problema o lo más importante."}, {"term": "Desenlace", "def": "Parte final de la narración, en la que se resuelve lo que pasó."}, {"term": "Ortografía", "def": "Conjunto de reglas para escribir las palabras correctamente."}], "practice": [{"q": "Escribe tres oraciones que describan tu habitación o tu calle usando al menos dos adjetivos.", "feedback": "Una buena respuesta dice cómo es el lugar y usa adjetivos, por ejemplo: «Mi habitación es pequeña y luminosa. Tiene una ventana grande». Fíjate en que cada oración empieza con mayúscula y acaba con punto. Describir bien exige observar con atención. Si puedes, añade lo que se oye o se huele."}, {"q": "Nombra las tres partes de una narración y explica qué ocurre en cada una.", "feedback": "Son el inicio, el nudo y el desenlace. En el inicio conocemos a los personajes y el lugar. En el nudo aparece el problema o lo más importante. En el desenlace se resuelve todo y la historia termina. Si nuestra historia tiene estas tres partes, se entiende mejor."}, {"q": "¿Por qué es importante escribir con claridad y revisar lo que escribimos?", "feedback": "Cuando escribimos con claridad, el lector entiende lo que queremos decir sin confundirse. Revisar nos permite corregir errores de ortografía y mejorar las ideas. Así respetamos a la persona que nos va a leer. El libro de Eclesiastés nos recuerda que conviene pensar antes de hablar, y lo mismo vale para escribir."}], "quiz": [{"q": "¿Qué dice un texto descriptivo?", "opts": [{"t": "Cómo es una persona, un animal o un lugar", "ok": true}, {"t": "Cuánto cuesta un objeto", "ok": false}, {"t": "Solo lo que sucedió ayer", "ok": false}]}, {"q": "¿Cuáles son las tres partes de una narración?", "opts": [{"t": "Título, dibujo y fin", "ok": false}, {"t": "Inicio, nudo y desenlace", "ok": true}, {"t": "Sol, luna y estrellas", "ok": false}]}, {"q": "¿Qué es un adjetivo?", "opts": [{"t": "Un signo de puntuación", "ok": false}, {"t": "Una parte de la narración", "ok": false}, {"t": "Una palabra que dice cómo es un nombre", "ok": true}]}, {"q": "¿Cuál de estas oraciones está bien escrita?", "opts": [{"t": "el campo es muy bonito", "ok": false}, {"t": "El campo es muy bonito.", "ok": true}, {"t": "el Campo es muy bonito", "ok": false}]}, {"q": "Según la lectura, ¿por qué conviene releer y corregir lo que escribimos?", "opts": [{"t": "Para gastar más papel", "ok": false}, {"t": "Para que el texto sea más largo", "ok": false}, {"t": "Para ordenar mejor las ideas y respetar al lector", "ok": true}]}], "verify": ["Regla de «m antes de b y p»: confirmar el ejemplo «también» y la formulación para este nivel.", "Eclesiastés 5:2: confirmar que la referencia se presenta como consejo sobre la prudencia al hablar."], "timeline": [{"when": "Paso 1", "what": "Observamos con atención y usamos los cinco sentidos."}, {"when": "Paso 2", "what": "Describimos cómo es algo con adjetivos."}, {"when": "Paso 3", "what": "Presentamos personajes y lugar en el inicio."}, {"when": "Paso 4", "what": "Contamos el problema en el nudo."}, {"when": "Paso 5", "what": "Resolvemos todo en el desenlace."}, {"when": "Paso 6", "what": "Releemos, corregimos la ortografía y mejoramos el texto."}], "scene": {"icons": ["✏️", "📖", "🖍️"], "palette": "blue"}, "media": [{"title": "Diccionario de la lengua española (RAE)", "what": "Ejemplo del diccionario al que acudir cuando dudamos al escribir.", "find": "Diccionario de la lengua española RAE portada Wikimedia Commons", "note": "Obra de la Real Academia Española; verificar licencia de la imagen."}, {"title": "Niña escribiendo en un cuaderno", "what": "Imagen de un niño escribiendo y revisando su texto.", "find": "child writing notebook Wikimedia Commons", "note": "Fotografía moderna; verificar licencia y que no muestre datos personales."}, {"title": "Manuscrito de Don Quijote de la Mancha (primera edición, portada)", "what": "Ejemplo de una obra narrativa con inicio, nudo y desenlace.", "find": "Don Quijote primera edición 1605 portada Wikimedia Commons", "note": "Miguel de Cervantes, 1605; dominio público."}]}, "p2:Mar": {"reading": ["Hace más de dos mil años, los romanos llegaron a la península ibérica. Eran un pueblo organizado y poderoso que venía de la ciudad de Roma. Con el tiempo dominaron casi toda la península y la llamaron Hispania. Los romanos vivieron aquí muchos siglos y dejaron una huella muy profunda. Ese proceso en el que los pueblos adoptaron las costumbres de Roma se llama romanización.", "Los romanos fundaron o ampliaron muchas ciudades. Construyeron plazas, templos, termas y teatros. Algunas ciudades actuales se levantan sobre ciudades romanas. También hicieron calzadas, que eran caminos anchos y firmes, hechos con piedras, para unir ciudades y facilitar el viaje de personas y mercancías. Se dice que «todos los caminos llevan a Roma» precisamente por ese enorme trabajo.", "Otra gran obra romana fue el acueducto. Un acueducto sirve para llevar agua desde un lugar lejano hasta una ciudad. El Acueducto de Segovia es uno de los más famosos y todavía hoy se puede visitar. Otro monumento muy importante es el Teatro Romano de Mérida, donde en la antigüedad se representaban obras. Estas construcciones nos muestran lo bien que trabajaban los romanos.", "Pero la herencia más grande de Roma es la lengua. Los romanos hablaban latín. Con el paso de los siglos, el latín fue cambiando poco a poco hasta convertirse en el castellano y en otras lenguas de la península. Muchas palabras que usamos cada día vienen del latín. Por ejemplo, agua viene de aqua, luna viene de luna y ciudad viene de civitas. Por eso decimos que el castellano es una lengua hija del latín.", "La Biblia dice que Jesús vino cuando se cumplió el tiempo. Mientras Roma gobernaba, las calzadas y una lengua común facilitaron los viajes y los mensajes. Más tarde, los primeros cristianos aprovecharon esos caminos para llevar la buena noticia de Jesús a muchos lugares. Así vemos cómo Dios guía la historia de los pueblos."], "glossary": [{"term": "Hispania", "def": "Nombre que los romanos dieron a la península ibérica, que formaba parte de su imperio."}, {"term": "Romanización", "def": "Proceso por el cual los pueblos conquistados adoptaron la lengua y las costumbres de Roma."}, {"term": "Calzada", "def": "Camino ancho y firme, hecho de piedras, que construían los romanos para unir ciudades."}, {"term": "Acueducto", "def": "Construcción que lleva agua desde un lugar lejano hasta una ciudad."}, {"term": "Latín", "def": "Lengua de los romanos, de la que proceden el castellano y otras lenguas."}, {"term": "Monumento", "def": "Obra construida para recordar a personas o hechos importantes del pasado."}], "practice": [{"q": "¿Qué cosas construyeron los romanos en Hispania y para qué servían?", "feedback": "Construyeron ciudades con plazas, templos y teatros, calzadas para viajar y acueductos para llevar agua. Las calzadas unían los pueblos y facilitaban el comercio. Los acueductos permitían que los habitantes tuvieran agua. Todo esto mejoró mucho la vida de las ciudades."}, {"q": "Explica por qué decimos que el castellano es hijo del latín. Da dos ejemplos de palabras.", "feedback": "Los romanos hablaban latín. Con los siglos, esa lengua fue cambiando hasta ser el castellano. Por eso muchas palabras castellanas se parecen a las latinas. Por ejemplo, agua viene de aqua y ciudad viene de civitas. Si conocemos el latín, entendemos mejor de dónde vienen nuestras palabras."}, {"q": "Según Gálatas 4:4, Dios envió a su Hijo cuando se cumplió el tiempo. ¿Cómo ayudó Roma a que la noticia de Jesús llegara lejos?", "feedback": "Roma tenía calzadas que unían muchas regiones y una lengua común que muchos podían entender. Eso facilitó que los primeros cristianos viajaran y llevaran su mensaje. No fue casualidad para Dios, que guía la historia. Así vemos que Dios puede usar hasta lo que construyen los pueblos para sus buenos planes."}], "quiz": [{"q": "¿Cómo llamaron los romanos a la península ibérica?", "opts": [{"t": "Hispania", "ok": true}, {"t": "Italia", "ok": false}, {"t": "Belén", "ok": false}]}, {"q": "¿Qué es una calzada romana?", "opts": [{"t": "Un tipo de zapato", "ok": false}, {"t": "Un camino ancho y firme que unía ciudades", "ok": true}, {"t": "Un tipo de casa", "ok": false}]}, {"q": "¿Para qué sirve un acueducto?", "opts": [{"t": "Para pescar", "ok": false}, {"t": "Para guardar monedas", "ok": false}, {"t": "Para llevar agua hasta una ciudad", "ok": true}]}, {"q": "¿Cuál es la herencia más importante de Roma, según la lectura?", "opts": [{"t": "Los zapatos", "ok": false}, {"t": "La lengua, porque el castellano viene del latín", "ok": true}, {"t": "Los volcanes", "ok": false}]}, {"q": "¿Qué palabra castellana viene del latín aqua?", "opts": [{"t": "Agua", "ok": true}, {"t": "Pan", "ok": false}, {"t": "Sol", "ok": false}]}], "verify": ["Fechas: la lectura dice «hace más de dos mil años»; confirmar que es adecuado para la llegada de Roma a la península.", "Acueducto de Segovia y Teatro Romano de Mérida: confirmar que se conservan y pueden visitarse.", "Etimologías: aqua, luna, civitas; confirmar las formas latinas.", "Gálatas 4:4 y la idea de la preparación providencial del mundo romano: confirmar el enfoque teológico."], "timeline": [{"when": "Hace más de 2000 años", "what": "Los romanos llegan a la península ibérica."}, {"when": "Con el tiempo", "what": "Dominan casi toda la península y la llaman Hispania."}, {"when": "Durante siglos", "what": "Los pueblos adoptan las costumbres de Roma: la romanización."}, {"when": "Obras", "what": "Se construyen calzadas, termas, teatros y acueductos."}, {"when": "Con los siglos", "what": "El latín cambia poco a poco hasta ser el castellano."}, {"when": "Cuando se cumplió el tiempo", "what": "Vino Jesús; las calzadas facilitan después el mensaje cristiano."}], "scene": {"icons": ["🏛️", "🛣️", "⚔️"], "palette": "rose"}, "media": [{"title": "Acueducto de Segovia", "what": "Gran obra romana que llevaba agua a la ciudad y aún se puede visitar.", "find": "Acueducto de Segovia Wikimedia Commons", "note": "Siglo I-II d. C.; fotografía moderna, verificar licencia."}, {"title": "Teatro Romano de Mérida", "what": "Teatro donde se representaban obras en la antigüedad.", "find": "Teatro Romano de Mérida Wikimedia Commons", "note": "Año 16-15 a. C.; fotografía moderna, verificar licencia."}, {"title": "Mapa de la Hispania romana", "what": "Muestra el territorio que los romanos llamaron Hispania.", "find": "Hispania romana mapa Wikimedia Commons", "note": "Mapa histórico; verificar licencia de la versión elegida."}], "map": {"region": "iberia", "markers": [{"name": "Segovia (acueducto)", "lat": 40.9, "lon": -4.1, "kind": "site"}, {"name": "Mérida (teatro romano)", "lat": 38.9, "lon": -6.3, "kind": "site"}, {"name": "Tarragona (antigua Tarraco)", "lat": 41.1, "lon": 1.3, "kind": "site"}]}}, "p2:Abr": {"reading": ["La Semana Santa es la semana en la que los cristianos recordamos los últimos días de Jesús en la tierra. Empieza el Domingo de Ramos, cuando Jesús entró en Jerusalén y la gente lo recibió con ramas. Continúa con el Jueves Santo, en el que recordamos la última cena. El Viernes Santo recordamos su muerte en la cruz. Termina con el Domingo de Resurrección, el día más alegre del año, porque Jesús venció a la muerte.", "En muchas ciudades de España hay cofradías, también llamadas hermandades. Una cofradía es un grupo de personas que se reúnen para vivir su fe y para sacar en procesión imágenes que representan escenas de la Pasión. Muchas cofradías existen desde hace siglos y algunas se fundaron en la Edad Media. Sus miembros se ayudan entre sí y también ayudan a los necesitados.", "En las procesiones se escuchan palabras propias de esta semana. Un paso es la imagen que se lleva sobre andas. Los costaleros son las personas que cargan con el paso. El nazareno es el que va vestido con túnica en la procesión. El capirote es el gorro alto y puntiagudo que lleva el nazareno. La saeta es un canto muy sentido que se dirige a las imágenes. Aprender este vocabulario nos ayuda a entender lo que vemos.", "Es importante recordar que la tradición no es solo una fiesta bonita. Todo nace de un relato verdadero. El Evangelio de Marcos cuenta que Jesús murió en una cruz y que hubo oscuridad en todo el país. Un oficial romano que estaba allí dijo que de verdad aquel hombre era Hijo de Dios. Tres días después, unas mujeres fueron al sepulcro y lo encontraron vacío. Un joven les dijo que Jesús había resucitado.", "Por eso los cristianos no vivimos tristes. Jesús dio su vida por nosotros y volvió a vivir. Esta es la mayor noticia de la historia. Las procesiones nos recuerdan este hecho, pero lo más importante es creer en Jesús y vivir como Él nos enseñó."], "glossary": [{"term": "Cofradía", "def": "Grupo de personas unidas por la fe que organizan procesiones y obras de ayuda; también se llama hermandad."}, {"term": "Procesión", "def": "Desfile religioso en el que se acompañan imágenes por las calles."}, {"term": "Paso", "def": "Imagen o conjunto de imágenes que se lleva sobre andas en una procesión."}, {"term": "Nazareno", "def": "Persona que va vestida con túnica en una procesión de Semana Santa."}, {"term": "Pasión", "def": "Los sufrimientos y la muerte de Jesús en la cruz."}, {"term": "Resurrección", "def": "Hecho de que Jesús volvió a vivir tres días después de su muerte."}], "practice": [{"q": "¿Qué es una cofradía y qué hacen sus miembros?", "feedback": "Una cofradía es un grupo de personas que se reúnen para vivir su fe. Organizan procesiones con imágenes de la Pasión y se ayudan entre sí. También ayudan a las personas necesitadas. Muchas llevan siglos de historia."}, {"q": "Elige tres palabras del vocabulario de Semana Santa y explica qué significan con tus palabras.", "feedback": "Puedes elegir paso, nazareno, costalero, capirote o saeta. Un paso es la imagen que se lleva en procesión, y un costalero es quien lo carga. El nazareno viste túnica y el capirote es su gorro alto. Una buena respuesta explica cada palabra con claridad y no la copia tal cual."}, {"q": "Según Marcos, ¿qué hechos ocurrieron el Viernes Santo y el domingo? ¿Por qué son una buena noticia?", "feedback": "El viernes Jesús murió en la cruz. El domingo unas mujeres encontraron el sepulcro vacío y oyeron que Jesús había resucitado. Es buena noticia porque Jesús venció a la muerte. Eso significa que podemos confiar en Él y que no tenemos que tener miedo. Por eso la Semana Santa termina con alegría."}], "quiz": [{"q": "¿Qué recordamos el Domingo de Resurrección?", "opts": [{"t": "Que Jesús volvió a vivir", "ok": true}, {"t": "Que comenzó el verano", "ok": false}, {"t": "Que Jesús nació en Belén", "ok": false}]}, {"q": "¿Qué es una cofradía?", "opts": [{"t": "Un tipo de comida", "ok": false}, {"t": "Un grupo de personas que viven su fe y organizan procesiones", "ok": true}, {"t": "Un monumento romano", "ok": false}]}, {"q": "¿Qué lleva el nazareno en la cabeza?", "opts": [{"t": "Un sombrero de paja", "ok": false}, {"t": "Una corona de oro", "ok": false}, {"t": "Un capirote", "ok": true}]}, {"q": "¿Qué es un paso?", "opts": [{"t": "Una imagen que se lleva sobre andas en la procesión", "ok": true}, {"t": "Un camino en la montaña", "ok": false}, {"t": "Un tipo de canción", "ok": false}]}, {"q": "¿De dónde nace la tradición de la Semana Santa, según la lectura?", "opts": [{"t": "De un cuento inventado", "ok": false}, {"t": "De una moda reciente", "ok": false}, {"t": "Del relato verdadero de la Pasión y la Resurrección", "ok": true}]}], "verify": ["Marcos 15:33-39 y 16:1-6: confirmar que el resumen (oscuridad, oficial romano, sepulcro vacío, joven que anuncia) se ajusta al texto.", "Origen medieval de algunas cofradías: la lectura lo dice con generalidad; confirmar.", "Definiciones de paso, costalero, nazareno, capirote y saeta: confirmar con el vocabulario usado por el centro."], "timeline": [{"when": "Domingo de Ramos", "what": "Jesús entra en Jerusalén y lo reciben con ramas."}, {"when": "Jueves Santo", "what": "Recordamos la última cena."}, {"when": "Viernes Santo", "what": "Recordamos su muerte en la cruz."}, {"when": "Tres días después", "what": "Unas mujeres encuentran el sepulcro vacío."}, {"when": "Domingo de Resurrección", "what": "Jesús venció a la muerte: el día más alegre."}, {"when": "Hoy", "what": "Las cofradías sacan procesiones y ayudan a los necesitados."}], "scene": {"icons": ["✝️", "🕯️", "🌿"], "palette": "violet"}, "media": [{"title": "Procesión de Semana Santa en Sevilla", "what": "Muestra un paso, los costaleros y los nazarenos con capirote.", "find": "Semana Santa Sevilla procesión paso nazarenos Wikimedia Commons", "note": "Fotografía moderna; verificar licencia."}, {"title": "Cristo crucificado (Velázquez)", "what": "Pintura española de Jesús en la cruz.", "find": "Velázquez Cristo crucificado Museo del Prado Wikimedia Commons", "note": "Diego Velázquez, hacia 1632; dominio público."}, {"title": "Paso de Semana Santa de Valladolid", "what": "Ejemplo de imagen tallada que se lleva sobre andas.", "find": "paso procesional Semana Santa Valladolid escultura Wikimedia Commons", "note": "Escultura barroca; fotografía, verificar licencia."}]}, "p2:May": {"reading": ["España está llena de ríos y de montañas. Los ríos recogen el agua de la lluvia y de la nieve y la llevan hasta el mar. El terreno por el que baja el agua de un río y de todos sus afluentes se llama cuenca. Los cinco grandes ríos de España son el Duero, el Tajo, el Guadiana, el Guadalquivir y el Ebro. Los cuatro primeros desembocan en el océano Atlántico, y el Ebro desemboca en el mar Mediterráneo.", "El Duero atraviesa la meseta norte y luego llega a Portugal. El Tajo cruza el centro de la península y también termina en Portugal. El Guadiana recorre el centro y el sur. El Guadalquivir es el gran río de Andalucía y pasa por ciudades como Córdoba y Sevilla. El Ebro cruza el noreste y nace en el norte de la península. Cada río ha dado vida a muchos pueblos y ciudades.", "El relieve es la forma que tiene la tierra: montañas, llanuras y costas. En el centro de la península hay una gran llanura alta que se llama meseta. Alrededor y dentro de ella hay cordilleras, que son grandes cadenas de montañas. Las principales son los Pirineos, en el norte, que separan España de Francia, el Sistema Central, que divide la meseta en dos, y la Cordillera Cantábrica, que corre junto al mar del norte. Las costas bañadas por el mar completan el paisaje.", "El agua es una bendición. La usamos para beber, para lavarnos, para regar los campos y para dar de beber a los animales. Sin agua no habría plantas ni alimentos. Por eso debemos cuidarla, no malgastarla y mantener limpios los ríos. Al cuidarla damos gracias al Creador.", "La Biblia compara a la persona que confía en Dios con un árbol plantado junto a corrientes de agua. Ese árbol tiene raíces profundas, da fruto a su tiempo y no se seca. De la misma manera, quien escucha la Palabra de Dios y la practica crece y da buenos frutos. Cuando veamos un río, podemos recordar esa promesa."], "glossary": [{"term": "Cuenca", "def": "Territorio por el que el agua de lluvia baja hacia un río y sus afluentes."}, {"term": "Afluente", "def": "Río pequeño que desemboca en otro río más grande."}, {"term": "Desembocadura", "def": "Lugar donde un río termina y entrega su agua al mar o a otro río."}, {"term": "Relieve", "def": "Conjunto de formas de la tierra: montañas, llanuras, valles y costas."}, {"term": "Meseta", "def": "Llanura extensa situada a gran altura sobre el nivel del mar."}, {"term": "Cordillera", "def": "Gran cadena de montañas."}], "practice": [{"q": "Nombra los cinco grandes ríos de España y di cuál desemboca en el Mediterráneo.", "feedback": "Son el Duero, el Tajo, el Guadiana, el Guadalquivir y el Ebro. Los cuatro primeros desembocan en el Atlántico. El Ebro es el que desemboca en el Mediterráneo. Para recordarlos, puedes dibujarlos en un mapa y escribir sus nombres."}, {"q": "¿Qué diferencia hay entre una meseta y una cordillera?", "feedback": "Una meseta es una llanura alta y extensa, mientras que una cordillera es una gran cadena de montañas. La meseta está en el centro de la península. Las cordilleras, como los Pirineos, rodean o cruzan el territorio. Las dos forman el relieve de España."}, {"q": "¿Por qué decimos que el agua es una bendición? Escribe dos formas de cuidarla.", "feedback": "El agua nos da vida porque sirve para beber, para cocinar, para lavarnos y para que crezcan las plantas. Sin ella no habría alimentos. Podemos cuidarla cerrando el grifo al cepillarnos los dientes o no tirando basura al río. Cuidarla es una forma de agradecer a Dios."}], "quiz": [{"q": "¿Cuál de estos ríos desemboca en el Mediterráneo?", "opts": [{"t": "El Tajo", "ok": false}, {"t": "El Ebro", "ok": true}, {"t": "El Duero", "ok": false}]}, {"q": "¿Qué es una cuenca?", "opts": [{"t": "Una montaña muy alta", "ok": false}, {"t": "Una playa de arena", "ok": false}, {"t": "El territorio por el que el agua baja hacia un río", "ok": true}]}, {"q": "¿Cómo se llama la gran llanura alta del centro de la península?", "opts": [{"t": "Meseta", "ok": true}, {"t": "Cordillera", "ok": false}, {"t": "Isla", "ok": false}]}, {"q": "¿Qué cordillera separa España de Francia?", "opts": [{"t": "El Sistema Central", "ok": false}, {"t": "Los Pirineos", "ok": true}, {"t": "La Cordillera Cantábrica", "ok": false}]}, {"q": "¿Con qué compara la Biblia a la persona que confía en Dios?", "opts": [{"t": "Con una montaña", "ok": false}, {"t": "Con una nube", "ok": false}, {"t": "Con un árbol plantado junto a corrientes de agua", "ok": true}]}], "verify": ["Desembocaduras: Duero, Tajo, Guadiana y Guadalquivir en el Atlántico; Ebro en el Mediterráneo. Confirmar que Duero y Tajo desembocan en Portugal (Oporto y Lisboa).", "Tajo, Duero y Guadiana atraviesan Portugal; confirmar la formulación de cada recorrido.", "Salmo 1:3: la lectura dice que quien medita la Palabra es como árbol plantado; confirmar el contexto."], "timeline": [{"when": "Paso 1", "what": "La lluvia y la nieve alimentan los ríos."}, {"when": "Paso 2", "what": "El agua baja por la cuenca hasta el mar."}, {"when": "Paso 3", "what": "Duero, Tajo, Guadiana y Guadalquivir desembocan en el Atlántico."}, {"when": "Paso 4", "what": "El Ebro desemboca en el Mediterráneo."}, {"when": "Paso 5", "what": "Cordilleras y meseta forman el relieve."}, {"when": "Paso 6", "what": "Cuidamos el agua y damos gracias al Creador."}], "scene": {"icons": ["🏞️", "⛰️", "💧"], "palette": "teal"}, "media": [{"title": "Delta del Ebro", "what": "Muestra cómo el Ebro desemboca en el mar Mediterráneo.", "find": "Delta del Ebro Wikimedia Commons", "note": "Fotografía o imagen de satélite; verificar licencia (las de la NASA suelen ser de dominio público)."}, {"title": "Mapa físico de España (ríos y relieve)", "what": "Permite ver los cinco ríos, la meseta y las cordilleras.", "find": "Mapa físico de España ríos cordilleras Wikimedia Commons", "note": "Verificar licencia de la versión elegida."}, {"title": "Pirineos (vista de las montañas)", "what": "Cordillera que separa España de Francia.", "find": "Pirineos paisaje Wikimedia Commons", "note": "Fotografía moderna; verificar licencia."}], "map": {"region": "iberia", "markers": [{"name": "Duero (desembocadura)", "lat": 41.1, "lon": -8.7, "kind": "river"}, {"name": "Tajo (desembocadura)", "lat": 38.7, "lon": -9.1, "kind": "river"}, {"name": "Guadiana (desembocadura)", "lat": 37.2, "lon": -7.4, "kind": "river"}, {"name": "Guadalquivir (Sevilla)", "lat": 37.4, "lon": -6.0, "kind": "river"}, {"name": "Ebro (desembocadura)", "lat": 40.7, "lon": 0.8, "kind": "river"}, {"name": "Pirineos", "lat": 42.7, "lon": 0.5, "kind": "mountain"}, {"name": "Sistema Central", "lat": 40.8, "lon": -4.0, "kind": "mountain"}, {"name": "Cordillera Cantábrica", "lat": 43.0, "lon": -5.5, "kind": "mountain"}]}}, "p2:Jun": {"reading": ["El castellano, también llamado español, es la lengua que hablas con tu familia. Nació en la península ibérica hace muchos siglos, a partir del latín. Con el tiempo, los españoles lo llevaron a otros continentes. Hoy se habla en más de veinte países y lo hablan más de quinientos millones de personas. Es una de las lenguas más habladas del mundo. Cuando hablamos castellano, compartimos palabras con millones de personas de muchos lugares.", "En España no se habla solo castellano. En algunas comunidades hay otras lenguas que también son oficiales. Estas lenguas se llaman cooficiales, porque lo son junto al castellano. Son el catalán, el gallego y el euskera. El catalán se habla en Cataluña, en las islas Baleares y en la Comunidad Valenciana, donde recibe el nombre de valenciano. El gallego se habla en Galicia. El euskera se habla en el País Vasco y en parte de Navarra. Todas estas lenguas son un tesoro y debemos respetarlas.", "Una forma muy bonita de usar la lengua son los refranes. Un refrán es una frase corta que da un consejo y que se ha repetido durante muchos años. Por ejemplo: «A quien madruga, Dios le ayuda» nos enseña a ser diligentes. «Más vale pájaro en mano que ciento volando» nos aconseja valorar lo que ya tenemos. «No hay mal que por bien no venga» nos anima a confiar cuando algo sale mal. Los refranes son sabiduría guardada en pocas palabras.", "La lengua es un don de Dios. Gracias a ella podemos dar las gracias, pedir perdón, contar cuentos y orar. La Biblia cuenta que en un tiempo todos los hombres hablaban una sola lengua. Más tarde, los pueblos se dispersaron y empezaron a hablar lenguas distintas. El profeta Sofonías anuncia que un día Dios dará a los pueblos una lengua pura para que todos lo invoquen y lo sirvan juntos.", "Por eso debemos usar bien el castellano. Podemos hablar con respeto, no decir palabras feas y leer buenos libros. Quien cuida su lengua cuida también a las personas que lo escuchan."], "glossary": [{"term": "Castellano", "def": "Lengua que nació en la península ibérica a partir del latín; es también llamada español."}, {"term": "Lengua cooficial", "def": "Lengua que es oficial junto al castellano en algunas comunidades de España."}, {"term": "Refrán", "def": "Frase corta y popular que da un consejo y se transmite desde hace mucho tiempo."}, {"term": "Euskera", "def": "Lengua propia del País Vasco y de parte de Navarra."}, {"term": "Catalán", "def": "Lengua que se habla en Cataluña, las islas Baleares y la Comunidad Valenciana, donde se llama valenciano."}, {"term": "Gallego", "def": "Lengua propia de Galicia."}], "practice": [{"q": "¿Cuáles son las tres lenguas cooficiales que menciona la lectura y dónde se hablan?", "feedback": "Son el catalán, el gallego y el euskera. El catalán se habla en Cataluña, en las islas Baleares y en la Comunidad Valenciana, donde se llama valenciano. El gallego se habla en Galicia, y el euskera en el País Vasco y en parte de Navarra. Todas conviven con el castellano y forman parte de la riqueza de España."}, {"q": "Elige un refrán y explica con tus palabras qué consejo da.", "feedback": "Por ejemplo, «A quien madruga, Dios le ayuda» aconseja no dejar las tareas para más tarde y ser diligente. «No hay mal que por bien no venga» nos anima a confiar cuando algo sale mal. Una buena explicación cuenta el consejo con palabras propias y da un ejemplo de la vida diaria."}, {"q": "¿Por qué la lengua es un don de Dios? Escribe dos cosas buenas que puedes hacer con tus palabras.", "feedback": "Con la lengua damos gracias, pedimos perdón y oramos, y gracias a ella nos comunicamos con los demás. Podemos animar a un amigo, contar un cuento o leer la Biblia en voz alta. Tus ejemplos deben ser cosas que puedas hacer de verdad. Usar bien las palabras es una manera de honrar a Dios."}], "quiz": [{"q": "¿De qué lengua nació el castellano?", "opts": [{"t": "Del latín", "ok": true}, {"t": "Del inglés", "ok": false}, {"t": "Del griego", "ok": false}]}, {"q": "¿Qué significa que una lengua sea cooficial?", "opts": [{"t": "Que está prohibida", "ok": false}, {"t": "Que es oficial junto al castellano en una comunidad", "ok": true}, {"t": "Que solo se escribe, pero no se habla", "ok": false}]}, {"q": "¿Qué es un refrán?", "opts": [{"t": "Una canción larga", "ok": false}, {"t": "Un tipo de mapa", "ok": false}, {"t": "Una frase corta que da un consejo", "ok": true}]}, {"q": "¿Qué consejo da el refrán «A quien madruga, Dios le ayuda»?", "opts": [{"t": "Ser diligente y no dejar las tareas para después", "ok": true}, {"t": "Dormir mucho", "ok": false}, {"t": "No ayudar a nadie", "ok": false}]}, {"q": "¿Qué anuncia el profeta Sofonías, según la lectura?", "opts": [{"t": "Que ya no habrá más lenguas", "ok": false}, {"t": "Que Dios dará a los pueblos una lengua pura", "ok": true}, {"t": "Que el latín volverá", "ok": false}]}], "verify": ["Cifras: la entrada hablaba de 22 países y 580 millones de personas; la lectura usa «más de veinte países» y «más de quinientos millones»; confirmar con una fuente actual.", "Lenguas cooficiales: confirmar dónde se hablan (catalán, valenciano, gallego, euskera en Navarra).", "Sofonías 3:9: confirmar la interpretación (lengua pura para invocar al Señor) y la mención de Babel/dispersión de las lenguas.", "Refranes: confirmar la formulación de los tres refranes citados."], "timeline": [{"when": "Hace siglos", "what": "El castellano nace en la península a partir del latín."}, {"when": "Con el tiempo", "what": "Los españoles lo llevan a otros continentes."}, {"when": "Hoy", "what": "Lo hablan más de 500 millones de personas."}, {"when": "En España", "what": "Catalán, gallego y euskera son lenguas cooficiales."}, {"when": "Refranes", "what": "Frases cortas guardan consejos repetidos durante años."}, {"when": "Siempre", "what": "Usamos bien la lengua: con respeto y buenas lecturas."}], "scene": {"icons": ["💬", "📚", "🗣️"], "palette": "amber"}, "media": [{"title": "Glosas Emilianenses", "what": "Primeros textos escritos con palabras en castellano.", "find": "Glosas Emilianenses Wikimedia Commons", "note": "Manuscrito medieval (siglos X-XI); dominio público."}, {"title": "Mapa de las lenguas de España", "what": "Muestra dónde se hablan castellano, catalán, gallego y euskera.", "find": "Mapa lenguas de España cooficiales Wikimedia Commons", "note": "Verificar licencia de la versión elegida."}, {"title": "Portada de Don Quijote de la Mancha (1605)", "what": "Gran obra escrita en castellano.", "find": "Don Quijote primera edición 1605 portada Wikimedia Commons", "note": "Miguel de Cervantes, 1605; dominio público."}], "map": {"region": "iberia", "markers": [{"name": "Barcelona (catalán)", "lat": 41.4, "lon": 2.2, "kind": "city"}, {"name": "Valencia (valenciano)", "lat": 39.5, "lon": -0.4, "kind": "city"}, {"name": "Palma (catalán)", "lat": 39.6, "lon": 2.7, "kind": "city"}, {"name": "Santiago de Compostela (gallego)", "lat": 42.9, "lon": -8.5, "kind": "city"}, {"name": "Bilbao (euskera)", "lat": 43.3, "lon": -2.9, "kind": "city"}]}}, "p2:Jul": {"reading": ["Hemos llegado al final del curso. Durante estos meses hemos recorrido España desde la ventana de nuestra casa. Empezamos por nuestra ciudad, con su historia y su escudo. Después subimos al mapa de la provincia y de la comunidad autónoma. Más tarde descubrimos cómo se celebra la Navidad en cada región y aprendimos a describir y a contar historias. Vimos lo que hicieron los romanos, entendimos la Semana Santa, conocimos los ríos y las montañas, y terminamos con la riqueza de nuestra lengua.", "Mirar atrás nos ayuda a aprender mejor. Esto se llama hacer una síntesis. Una síntesis es un resumen en el que decimos lo más importante de lo que hemos estudiado. Para hacerla, recordamos lo que más nos gustó y apuntamos las cosas que aún queremos saber. Así vemos cuánto hemos crecido. También descubrimos que nos queda mucho por aprender, y eso es bueno.", "Con todo el trabajo del año vamos a crear un Libro de España. Tendrá una portada con un título y un dibujo, y un índice que dirá en qué página está cada trabajo. El índice sirve para encontrar rápido lo que buscamos. Después prepararemos una presentación oral. Hablar ante la familia exige orden. Primero saludamos, luego contamos lo más interesante y por último damos las gracias. Debemos hablar despacio, mirar a las personas y hablar claro.", "Todo lo que hemos aprendido es una herencia. Nuestros antepasados construyeron ciudades, escribieron libros, cantaron villancicos y defendieron su fe. Hoy la recibimos con gratitud. Dar las gracias es una virtud muy hermosa. Nos hace humildes y alegres, porque reconocemos que no lo hemos conseguido solos.", "La Biblia nos pide no olvidar lo que han visto nuestros ojos y contárselo a los hijos. Eso hacemos al recordar lo aprendido y al compartirlo en familia. Cuando oremos, podemos dar gracias a Dios por nuestro país, nuestra lengua y nuestra historia. Todo es regalo suyo."], "glossary": [{"term": "Síntesis", "def": "Resumen que recoge lo más importante de lo estudiado."}, {"term": "Portada", "def": "Primera página de un libro, con el título y un dibujo."}, {"term": "Índice", "def": "Lista que indica en qué página está cada parte de un libro."}, {"term": "Presentación oral", "def": "Exposición en voz alta ante un público, con orden y claridad."}, {"term": "Herencia", "def": "Conjunto de cosas valiosas que recibimos de quienes vivieron antes que nosotros."}, {"term": "Gratitud", "def": "Sentimiento de agradecimiento hacia Dios y hacia las personas por lo que nos dan."}], "practice": [{"q": "¿Qué es una síntesis y para qué sirve al terminar el curso?", "feedback": "Una síntesis es un resumen que recoge lo más importante de lo que hemos aprendido. Al terminar el curso nos sirve para recordar y para ver cuánto hemos crecido. También nos ayuda a descubrir qué queremos aprender después. Para hacerla bien, elegimos lo esencial y no copiamos todo."}, {"q": "Explica la diferencia entre una portada y un índice.", "feedback": "La portada es la primera página y lleva el título y un dibujo. El índice es una lista que dice en qué página está cada trabajo del libro. La portada presenta el libro y el índice ayuda a encontrar lo que buscamos. Un libro bien hecho necesita las dos cosas."}, {"q": "¿Por qué es importante dar gracias por la historia, la lengua y el país que hemos recibido?", "feedback": "Porque todo eso es una herencia que no hemos conseguido solos. Otras personas trabajaron, escribieron y cuidaron lo que hoy disfrutamos. Dar gracias nos hace humildes y alegres. Además, reconocemos que todo viene de Dios, que es quien da lo bueno que tenemos."}], "quiz": [{"q": "¿Qué es una síntesis?", "opts": [{"t": "Un resumen con lo más importante", "ok": true}, {"t": "Una lista de errores", "ok": false}, {"t": "Un tipo de mapa", "ok": false}]}, {"q": "¿Para qué sirve un índice en un libro?", "opts": [{"t": "Para colorear las páginas", "ok": false}, {"t": "Para indicar en qué página está cada parte", "ok": true}, {"t": "Para escribir el título", "ok": false}]}, {"q": "¿Qué conviene hacer en una presentación oral?", "opts": [{"t": "Hablar muy rápido", "ok": false}, {"t": "Mirar al suelo", "ok": false}, {"t": "Hablar despacio, claro y con orden", "ok": true}]}, {"q": "¿Qué es una herencia en el sentido de la lectura?", "opts": [{"t": "Lo valioso que recibimos de quienes vivieron antes", "ok": true}, {"t": "Una casa nueva", "ok": false}, {"t": "Un juguete", "ok": false}]}, {"q": "¿Qué nos pide la Biblia en Deuteronomio 4:9, según la lectura?", "opts": [{"t": "Olvidar el pasado", "ok": false}, {"t": "No olvidar lo que han visto nuestros ojos y contarlo a los hijos", "ok": true}, {"t": "Viajar mucho", "ok": false}]}], "verify": ["Deuteronomio 4:9: confirmar que el sentido de «no olvidar lo que vieron tus ojos y enseñarlo a tus hijos» se ajusta al texto.", "Resumen del año: la lectura enumera los temas del curso; confirmar que coincide con la programación final del centro."], "timeline": [{"when": "Paso 1", "what": "Recordamos lo aprendido, de nuestra ciudad a la lengua."}, {"when": "Paso 2", "what": "Hacemos una síntesis con lo más importante."}, {"when": "Paso 3", "what": "Apuntamos lo que aún queremos saber."}, {"when": "Paso 4", "what": "Creamos el Libro de España con portada e índice."}, {"when": "Paso 5", "what": "Preparamos la presentación oral: saludar, contar y agradecer."}, {"when": "Paso 6", "what": "Damos gracias a Dios por nuestro país y nuestra historia."}], "scene": {"icons": ["📘", "🎉", "🙏"], "palette": "blue"}, "media": [{"title": "Mapa de España", "what": "Imagen para la portada del Libro de España.", "find": "Mapa de España Wikimedia Commons", "note": "Verificar licencia de la versión elegida."}, {"title": "Escudo de España", "what": "Símbolo del país que puede ilustrar el libro y la presentación.", "find": "Escudo de España Wikimedia Commons", "note": "Símbolo oficial; verificar licencia de la versión elegida."}, {"title": "Niños en una presentación oral", "what": "Ejemplo de cómo hablar ante la familia mirando a las personas.", "find": "children oral presentation classroom Wikimedia Commons", "note": "Fotografía moderna; verificar licencia y que no muestre datos personales."}]}});
